function getDefaultFallbackImage(name, code) {
  let lower = ((name || '') + ' ' + (code || '')).toLowerCase();
  if (lower.includes('panadol')) {
    return 'https://images.unsplash.com/photo-1584308666744-24d5c474f2ae?w=800&auto=format&fit=crop&q=80';
  }
  if (lower.includes('berocca') || lower.includes('sủi')) {
    return 'https://images.unsplash.com/photo-1471864190281-a93a3070b6de?w=800&auto=format&fit=crop&q=80';
  }
  if (lower.includes('prospan') || lower.includes('siro')) {
    return 'https://images.unsplash.com/photo-1514733670139-4d87a1941d55?w=800&auto=format&fit=crop&q=80';
  }
  if (lower.includes('tobradex') || lower.includes('mắt') || lower.includes('nhỏ')) {
    return 'https://images.unsplash.com/photo-1576602976047-174e57a47881?w=800&auto=format&fit=crop&q=80';
  }
  if (lower.includes('enterogermina') || lower.includes('men') || lower.includes('ống')) {
    return 'https://images.unsplash.com/photo-1587854692152-cbe660dbde88?w=800&auto=format&fit=crop&q=80';
  }
  return 'https://images.unsplash.com/photo-1607613009820-a29f7bb81c04?w=800&auto=format&fit=crop&q=80';
}

function formatLotDateImageUrl(raw, name, code) {
  if (!raw) return getDefaultFallbackImage(name, code);
  let str = String(raw).trim();
  let imgMatch = str.match(/=IMAGE\s*\(\s*["']([^"']+)["']/i);
  if (imgMatch) str = imgMatch[1].trim();

  if (/^\d{5,}$/.test(str)) {
    return getDefaultFallbackImage(name, code);
  }

  let driveMatch = str.match(/(?:\/d\/|id=|file\/d\/)([a-zA-Z0-9-_]{20,})/);
  if (driveMatch && (str.includes('drive.google.com') || str.includes('docs.google.com'))) {
    return 'https://lh3.googleusercontent.com/d/' + driveMatch[1];
  }

  if (str.startsWith('http://') || str.startsWith('https://') || str.startsWith('//') || str.startsWith('data:image')) {
    return str;
  }

  return getDefaultFallbackImage(name, code);
}

function parseLotDateRows(rows) {
  if (!rows || !rows.length) return [];
  let result = [];
  let startIndex = 0;
  if (rows.length > 0) {
    let headerStr = rows[0].join(' ').toLowerCase();
    if (headerStr.includes('mã') || headerStr.includes('code') || headerStr.includes('tên') || headerStr.includes('ảnh') || headerStr.includes('date') || headerStr.includes('hình')) {
      startIndex = 1;
    }
  }

  let urlColIndex = -1;
  for (let c = 2; c < Math.min(6, (rows[1] || []).length); c++) {
    for (let r = 1; r < Math.min(10, rows.length); r++) {
      let cell = String(rows[r][c] || '').toLowerCase();
      if (cell.includes('http') || cell.includes('drive.google')) {
        urlColIndex = c;
        break;
      }
    }
    if (urlColIndex !== -1) break;
  }

  for (let i = startIndex; i < rows.length; i++) {
    let row = rows[i];
    if (!row || !row.length) continue;
    let code = String(row[0] || '').trim();
    let name = String(row[1] || '').trim();
    let rawImg = urlColIndex !== -1 ? row[urlColIndex] : row[2];

    if (!name && code) name = 'Sản phẩm ' + code;
    if (code || name) {
      let img = formatLotDateImageUrl(rawImg, name, code);
      result.push({
        id: 'LD-' + (i + 1),
        productCode: code,
        productName: name,
        imageUrl: img
      });
    }
  }
  return result;
}

