var fetchLotDateData = async () => {
  let url = getLotDateSheetUrl();
  let parsed = rg(url);
  if (typeof document < 'u' && parsed && parsed.sheetId) {
    let sheetNamesToTry = ['LoDate', 'ViTriLoDate', 'Lô Date', ''];
    for (let sName of sheetNamesToTry) {
      try {
        let rows = await ig(parsed.sheetId, sName ? null : parsed.gid, sName);
        let items = parseLotDateRows(rows);
        if (items.length > 0) {
          try {
            localStorage.setItem(Kh.LOTDATE_CACHE, JSON.stringify(items));
            localStorage.setItem(Kh.LOTDATE_LAST_SYNC, new Date().toISOString());
          } catch {}
          return { data: items, source: 'Google Sheet Lô Date (' + items.length.toLocaleString('vi-VN') + ' sản phẩm)' };
        }
      } catch (e) {}
    }
  }

  let csvInfo = ag(url, 'LoDate');
  if (csvInfo) {
    try {
      let resp = await fetch(csvInfo.url);
      if (resp.ok) {
        let table = og(await resp.text());
        let items = parseLotDateRows(table);
        if (items.length > 0) {
          try {
            localStorage.setItem(Kh.LOTDATE_CACHE, JSON.stringify(items));
            localStorage.setItem(Kh.LOTDATE_LAST_SYNC, new Date().toISOString());
          } catch {}
          return { data: items, source: 'Google Sheet Lô Date (' + items.length.toLocaleString('vi-VN') + ' sản phẩm)' };
        }
      }
    } catch (e) {}
  }

  let cached = localStorage.getItem(Kh.LOTDATE_CACHE);
  if (cached) {
    try {
      return { data: JSON.parse(cached), source: 'Bộ nhớ đệm Lô Date (Cache)' };
    } catch {}
  }

  return { data: defaultLotDateDemoList, source: 'Dữ liệu mẫu Lô Date (Demo)' };
};
